<form class="filters" method="get"><input name="q" value="<?= e($q) ?>" placeholder="<?= e(__('actions.search')) ?>"><button class="btn btn-primary" type="submit"><?= e(__('actions.search')) ?></button></form>
<?php if ($page['rows'] === []): ?><p class="empty"><?= e(__('empty.results')) ?></p><?php else: ?>
<div class="table-wrap"><table><thead><tr><th><?= e(__('fields.name')) ?></th><th><?= e(__('fields.email')) ?></th><th><?= e(__('fields.phone')) ?></th><th><?= e(__('fields.status')) ?></th></tr></thead><tbody><?php foreach ($page['rows'] as $row): ?><tr><td data-label="Name"><a href="<?= e(url('/admin/customers/' . $row['id'])) ?>"><?= e($row['name']) ?></a></td><td data-label="Email"><?= e($row['email']) ?></td><td data-label="Phone"><?= e((string) $row['phone']) ?></td><td data-label="Status"><?= status_badge((int) $row['is_active'] === 1 ? 'Active' : 'Suspended', (int) $row['is_active'] === 1 ? 'success' : 'warning') ?></td></tr><?php endforeach; ?></tbody></table></div><?= paginator($page, '/admin/customers') ?>
<?php endif; ?>
